-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["modules/custom/lua/quest_workarounds.lua"]={["Path"]="modules/custom/lua/quest_workarounds.lua",["SHA256"]="54c849a531a474b507329a199fc6c713ce0bb89fa04c70ade46495760a7de8c0",["Text"]="-----------------------------------\n-- This module is a compilation of overrides to temporarily fix\n-- parts of quests that are not currently fully functional due to something\n-- larger (like a system) not being implemented/operable.\n-----------------------------------\n-- Include the following:\n-- - Explanation of what quest(s) needs temporary fix\n-- - Link to issue reported on LSB\n-- - Explanation (if known) of how to fix\n-- - Include a TODO so it can be searched.\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('quest_workarounds')\n-----------------------------------\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    -- Bastok zones don't currently produce NONE weather, so we are adding SUNSHINE as an accepted weather so the quest becomes completable.\n    -- See: https://github.com/LandSandBoat/server/pull/5831\n    xi.module.modifyInteractionEntry('scripts/quests/bastok/Wish_Upon_a_Star', function(quest)\n        quest.sections[2][xi.zone.BASTOK_MARKETS]['Enu'].onTrade = function(player, npc, trade)\n        local isNight = VanadielTOTD() == xi.time.NIGHT or VanadielTOTD() == xi.time.MIDNIGHT\n            if npcUtil.tradeHasExactly(trade, xi.item.FALLEN_STAR) then\n                if\n                    player:getWeather() == xi.weather.NONE or\n                    player:getWeather() == xi.weather.SUNSHINE and\n                    isNight\n                then\n                    return quest:progressEvent(334)\n                else\n                    return quest:event(337)\n                end\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/missions/mission_adjustments.lua"]={["Path"]="modules/era/lua/missions/mission_adjustments.lua",["SHA256"]="d92e4135cf32c1dfedbb7f2ecd01681e994debdb5902824eb49ea4fd9d96d42d",["Text"]="-----------------------------------\n-- Mission Adjustments\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_mission_adjustments')\n\nm:addOverrideByEra('xi.server.onServerStart', {\n    [xi.expansion.ROV] = function()\n        super()\n\n        -- Rhapsodies of Vana'diel Era\n        -- Source: https://forum.square-enix.com/ffxi/threads/51154-Aug.-3-2016-%28JST%29-Version-Update\n        ------------------------------------\n        --- ToAU Mission 18 \"Passing Glory\": Adds a forced JST midnight wait to begin Mission 18 (Passing Glory)\n        ------------------------------------\n        xi.module.modifyInteractionEntry('scripts/missions/toau/17_Guests_of_the_Empire', function(mission)\n            local whitegate = mission.sections[1][xi.zone.AHT_URHGAN_WHITEGATE]\n\n            whitegate.onEventFinish[3078] = function(player, csid, option, npc)\n                if mission:complete(player) then\n                    player:setLocalVar('Mission[4][17]mustZone', 1)\n                    player:setCharVar('Mission[4][17]Timer', 1, JstMidnight()) -- Module change: Start JST midnight timer\n                end\n            end\n        end)\n\n        xi.module.modifyInteractionEntry('scripts/missions/toau/18_Passing_Glory', function(mission)\n            mission.sections[1].check = function(player, currentMission, missionStatus, vars)\n                return currentMission == mission.missionId and\n                    not mission:getMustZone(player) and\n                    mission:getVar(player, 'Timer') == 0\n            end\n        end)\n\n        ------------------------------------\n        --- ToAU Mission 25 \"Playing the Part\": Adds a forced JST midnight wait to begin Mission 25 (Playing the Part)\n        ------------------------------------\n        xi.module.modifyInteractionEntry('scripts/missions/toau/24_Foiled_Ambition', function(mission)\n            local whitegate = mission.sections[1][xi.zone.AHT_URHGAN_WHITEGATE]\n\n            whitegate.onEventFinish[3097] = function(player, csid, option, npc)\n                if mission:complete(player) then\n                    player:setLocalVar('Mission[4][24]mustZone', 1)\n                    player:setCharVar('Mission[4][24]Timer', 1, JstMidnight()) -- Module change: Start JST midnight timer\n                end\n            end\n        end)\n\n        xi.module.modifyInteractionEntry('scripts/missions/toau/25_Playing_the_Part', function(mission)\n            local whitegate = mission.sections[1][xi.zone.AHT_URHGAN_WHITEGATE]\n\n            whitegate['Naja_Salaheem'].onTrigger = function(player, npc)\n                if\n                    not mission:getMustZone(player) and\n                    mission:getVar(player, 'Timer') == 0 -- Module change: Check JST midnight timer\n                then\n                    return mission:progressEvent(3110)\n                else\n                    local dialog = mission:getVar(player, 'Option') + 1 -- Captured values 1 and 2\n                    if dialog == 1 then\n                        mission:setVar(player, 'Option', 1)\n                    else\n                        mission:setVar(player, 'Option', 0)\n                    end\n\n                    return mission:event(3098, xi.besieged.getMercenaryRank(player), 1, 0, 0, 0, 0, 0, dialog, 0)\n                end\n            end\n        end)\n\n        ------------------------------------\n        --- ToAU Mission 33 \"Sentinels' Honor\": Adds a forced JST midnight wait to begin Mission 33 (Sentinels' Honor)\n        ------------------------------------\n        xi.module.modifyInteractionEntry('scripts/missions/toau/32_In_the_Blood', function(mission)\n            local whitegate = mission.sections[1][xi.zone.AHT_URHGAN_WHITEGATE]\n\n            whitegate.onEventFinish[3113] = function(player, csid, option, npc)\n                if mission:complete(player) then\n                    player:setLocalVar('Mission[4][32]mustZone', 1)\n                    player:setCharVar('Mission[4][32]Timer', 1, JstMidnight()) -- Module change: Start JST midnight timer\n                end\n            end\n        end)\n\n        xi.module.modifyInteractionEntry('scripts/missions/toau/33_Sentinels_Honor', function(mission)\n            local whitegate = mission.sections[1][xi.zone.AHT_URHGAN_WHITEGATE]\n\n            whitegate['Naja_Salaheem'].onTrigger = function(player, npc)\n                local hasZoned      = not mission:getMustZone(player)\n                local hasTimePassed = mission:getVar(player, 'Timer') == 0 -- Module change: Check JST midnight timer\n\n                -- Calculate event.\n                local eventId = (hasZoned and hasTimePassed) and 3130 or 3120\n\n                -- Calculate dialog.\n                local dialog = 2\n\n                if not hasTimePassed then -- Dialog parameter cycles between 0 and 2 until time lockout is over. At that point, option 0 stops happening.\n                    dialog = mission:getVar(player, 'Option')\n                    if dialog == 0 then\n                        mission:setVar(player, 'Option', 2)\n                    else\n                        mission:setVar(player, 'Option', 0)\n                    end\n                end\n\n                return mission:event(eventId, xi.besieged.getMercenaryRank(player), 1, 0, 0, 0, 0, 0, dialog, 0)\n            end\n        end)\n\n        ------------------------------------\n        --- ToAU Mission 38 \"Stirrings of War\": Adds a forced JST midnight wait to begin Mission 38 (Stirrings of War)\n        ------------------------------------\n        xi.module.modifyInteractionEntry('scripts/missions/toau/37_Path_of_Blood', function(mission)\n            local whitegate = mission.sections[1][xi.zone.AHT_URHGAN_WHITEGATE]\n\n            whitegate.onEventFinish[3220] = function(player, csid, option, npc)\n                if mission:complete(player) then\n                    player:setLocalVar('Mission[4][37]mustZone', 1)\n                    player:setCharVar('Mission[4][37]Timer', 1, JstMidnight()) -- Module change: Start JST midnight timer\n                end\n            end\n        end)\n\n        xi.module.modifyInteractionEntry('scripts/missions/toau/38_Stirrings_of_War', function(mission)\n            mission.sections[1].check = function(player, currentMission, missionStatus, vars)\n                return currentMission == mission.missionId and\n                    not mission:getMustZone(player) and\n                    mission:getVar(player, 'Timer') == 0 -- Module change: Check JST midnight timer\n            end\n        end)\n    end,\n\n    [xi.expansion.SOA] = function()\n        super()\n\n        -- Seekers of Adoulin Era\n        -----------------------------------\n        -- TOAU Mission 4 \"Knight of Gold\": Adds a forced JST midnight wait to begin Mission 4 (Knight of Gold)\n        -- Source: https://forum.square-enix.com/ffxi/threads/42614-Jun-17-2014-%28JST%29-Version-Update\n        -----------------------------------\n        xi.module.modifyInteractionEntry('scripts/missions/toau/03_President_Salaheem', function(mission)\n            local whitegate = mission.sections[1][xi.zone.AHT_URHGAN_WHITEGATE]\n\n            whitegate['Naja_Salaheem'].onTrigger = function(player, npc)\n                if player:getMissionStatus(mission.areaId) == 1 then\n                    if\n                        not mission:getMustZone(player) and\n                        mission:getVar(player, 'Timer') == 0 -- Module change: Check JST midnight timer\n                    then\n                        return mission:progressEvent(3020, { text_table = 0 }) -- Enter Not-Trion.\n                    else\n                        return mission:event(3003, { [0] = xi.besieged.getMercenaryRank(player), text_table = 0 }) -- Default Dialog.\n                    end\n                else\n                    return mission:progressEvent(73, { text_table = 0 }) -- Mog Locker scam.\n                end\n            end\n\n            whitegate.onEventFinish[73] = function(player, csid, option, npc)\n                player:setMissionStatus(mission.areaId, 1)\n                mission:setMustZone(player)\n                mission:setVar(player, 'Timer', 1, JstMidnight()) -- Module change: Start JST midnight timer\n            end\n        end)\n\n        -----------------------------------\n        -- ToAU Mission 6 \"Easterly Winds\": Adds a forced JST midnight wait to begin Mission 6 (Easterly Winds)\n        -- Source: https://forum.square-enix.com/ffxi/threads/44090-Sep-9-2014-%28JST%29-Version-Update\n        -----------------------------------\n        xi.module.modifyInteractionEntry('scripts/missions/toau/05_Confessions_of_Royalty', function(mission)\n            local chateau = mission.sections[1][xi.zone.CHATEAU_DORAGUILLE]\n\n            chateau.onEventFinish[564] = function(player, csid, option, npc)\n                if option == 1 then\n                    player:delKeyItem(xi.keyItem.RAILLEFALS_LETTER)\n                    if mission:complete(player) then\n                        player:setVar('Mission[4][5]Timer', 1, JstMidnight()) -- Module change: Start JST midnight timer\n                    end\n                end\n            end\n        end)\n\n        xi.module.modifyInteractionEntry('scripts/missions/toau/06_Easterly_Winds', function(mission)\n            local rulude = mission.sections[1][xi.zone.RULUDE_GARDENS]\n\n            rulude.onTriggerAreaEnter[1] = function(player, triggerArea)\n                -- Module change: Check JST midnight timer before allowing player to progress the mission\n                if mission:getVar(player, 'Timer') == 0 then\n                    return mission:progressEvent(10094)\n                end\n            end\n        end)\n\n        -----------------------------------\n        -- TOAU Mission 8 \"A Mercenary Life\": Adds a forced JST midnight wait to begin Mission 8 (A Mercenary Life)\n        -- Source: https://forum.square-enix.com/ffxi/threads/42614-Jun-17-2014-%28JST%29-Version-Update\n        -----------------------------------\n        xi.module.modifyInteractionEntry('scripts/missions/toau/07_Westerly_Winds', function(mission)\n            local whitegate = mission.sections[1][xi.zone.AHT_URHGAN_WHITEGATE]\n\n            whitegate.onEventFinish[3028] = function(player, csid, option, npc)\n                if mission:complete(player) then\n                    player:delKeyItem(xi.keyItem.RAILLEFALS_NOTE)\n                    player:setLocalVar('Mission[4][7]mustZone', 1)\n                    player:setCharVar('Mission[4][7]Timer', 1, JstMidnight()) -- Module change: Start JST midnight timer\n                end\n            end\n        end)\n\n        xi.module.modifyInteractionEntry('scripts/missions/toau/08_A_Mercenary_Life', function(mission)\n            local whitegate = mission.sections[2][xi.zone.AHT_URHGAN_WHITEGATE]\n\n            whitegate.onTriggerAreaEnter[3] = function(player, triggerArea)\n                -- Module change: Check JST midnight timer before allowing player to progress the mission\n                if mission:getVar(player, 'Timer') == 0 then\n                    return mission:progressEvent(3050, 3, 3, 3, 3, 3, 3, 3, 3, 0)\n                end\n            end\n        end)\n\n        -----------------------------------\n        -- San d'Oria Mission 6-2 \"Ranperre's Final Rest\": Restores the JST midnight wait for the gate guards to decipher the ancient book.\n        -- The June 17, 2014 version update decreased the required wait.\n        -- Source: https://forum.square-enix.com/ffxi/threads/42614-Jun-17-2014-%28JST%29-Version-Update\n        -----------------------------------\n        xi.module.modifyInteractionEntry('scripts/missions/sandoria/6_2_Ranperres_Final_Rest', function(mission)\n            local southern = mission.sections[2][xi.zone.SOUTHERN_SAN_DORIA]\n            local northern = mission.sections[2][xi.zone.NORTHERN_SAN_DORIA]\n\n            local handoverEvents =\n            {\n                { section = southern, eventId = 1035 },\n                { section = southern, eventId = 1036 },\n                { section = northern, eventId = 1035 },\n            }\n\n            local gateGuards =\n            {\n                { section = southern, name = 'Ambrotien', waitEvent = 1038 },\n                { section = southern, name = 'Endracion', waitEvent = 1037 },\n                { section = northern, name = 'Grilau', waitEvent = 1037 },\n            }\n\n            -- Start the timer when the book is handed to a gate guard.\n            for _, handover in ipairs(handoverEvents) do\n                local baseHandler = handover.section.onEventFinish[handover.eventId]\n\n                handover.section.onEventFinish[handover.eventId] = function(player, csid, option, npc)\n                    baseHandler(player, csid, option, npc)\n                    mission:setVar(player, 'Timer', 1, JstMidnight())\n                end\n            end\n\n            -- Hold players at the \"still deciphering\" dialogue until the timer expires.\n            for _, guard in ipairs(gateGuards) do\n                local baseOnTrigger = guard.section[guard.name].onTrigger\n\n                guard.section[guard.name].onTrigger = function(player, npc)\n                    if\n                        player:getMissionStatus(mission.areaId) == 4 and\n                        mission:getVar(player, 'Timer') ~= 0\n                    then\n                        return mission:progressEvent(guard.waitEvent)\n                    end\n\n                    return baseOnTrigger(player, npc)\n                end\n            end\n        end)\n\n        -----------------------------------\n        -- San d'Oria Mission 8-1 \"Coming of Age\": Restores the JST midnight wait before the final cutscene in Northern San d'Oria.\n        -- The July 8, 2014 version update reduced the wait to one Earth minute.\n        -- Source: https://forum.square-enix.com/ffxi/threads/43135-Jul-8-2014-%28JST%29-Version-Update\n        -----------------------------------\n        xi.module.modifyInteractionEntry('scripts/missions/sandoria/8_1_Coming_of_Age', function(mission)\n            local chateau = mission.sections[2][xi.zone.CHATEAU_DORAGUILLE]\n\n            -- Copy of the base handler with the one minute wait extended to JST midnight\n            chateau.onEventFinish[102] = function(player, csid, option, npc)\n                if mission:complete(player) then\n                    mission:setVar(player, 'Progress', JstMidnight())\n                    player:delKeyItem(xi.keyItem.DROPS_OF_AMNIO)\n                end\n            end\n        end)\n    end,\n})\n"},["modules/era/lua/quests/ahturhgan/beginnings.lua"]={["Path"]="modules/era/lua/quests/ahturhgan/beginnings.lua",["SHA256"]="85954ad27e6a89006d3d6136c907ec65363f2b7caf2507a0a8df32f09a1df469",["Text"]="-----------------------------------\n-- Beginnings (BLU AF1)\n-- Restores the JST midnight wait before Waoud offers Omens.\n-- The June 7, 2016 version update shortened the wait to one minute.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/50760-Jun.-7-2016-(JST)-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_beginnings', xi.pre(xi.expansion.ROV))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/ahtUrhgan/BLU_AF1_Beginnings', function(quest)\n        local whitegate = quest.sections[2][xi.zone.AHT_URHGAN_WHITEGATE]\n\n        -- Copy of the base handler. Omens is offered at JST midnight.\n        whitegate.onEventFinish[707] = function(player, csid, option, npc)\n            if quest:complete(player) then\n                xi.quest.setMustZone(player, xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.OMENS)\n                xi.quest.setVar(player, xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.OMENS, 'Timer', JstMidnight()) -- Module change\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/ahturhgan/delivering_the_goods.lua"]={["Path"]="modules/era/lua/quests/ahturhgan/delivering_the_goods.lua",["SHA256"]="ac54fabae1fdcca2b9dca61f5544f1ee5e3a4567227ef045e793680e55a36dff",["Text"]="-----------------------------------\n-- Delivering the Goods\n-- Restores the JST midnight wait before Vanishing Act opens.\n-- The September 9, 2014 version update shortened the wait to one minute.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/44090-Sep-9-2014-(JST)-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_delivering_the_goods', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/ahtUrhgan/Delivering_the_Goods', function(quest)\n        local whitegate = quest.sections[3][xi.zone.AHT_URHGAN_WHITEGATE]\n\n        -- Copy of the base handler. Vanishing Act opens at JST midnight.\n        whitegate.onEventFinish[41] = function(player, csid, option, npc)\n            if quest:complete(player) then\n                xi.quest.setVar(player, xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.VANISHING_ACT, 'Stage', JstMidnight()) -- Module change\n\n                -- Player must zone before being able to flag the next quest\n                player:needToZone(true)\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/ahturhgan/got_it_all.lua"]={["Path"]="modules/era/lua/quests/ahturhgan/got_it_all.lua",["SHA256"]="624d47d5efa12006691da6ed40d58489f5231f56dfbd615fbe4cb39b1a2a4d64",["Text"]="-----------------------------------\n-- Got It All\n-- Restores the real-midnight wait before Tehf Kimasnahya's final event.\n-- The July 8, 2014 version update abolished the JST midnight wait.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/43135-Jul-8-2014-(JST)-Version-Update\n-- Source: https://wiki.ffo.jp/html/5374.html\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_got_it_all', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/ahtUrhgan/Got_It_All', function(quest)\n        local whitegate = quest.sections[2][xi.zone.AHT_URHGAN_WHITEGATE]\n\n        -- Restores the JST Midnight Wait\n        whitegate.onEventFinish[527] = function(player, csid, option, npc)\n            quest:setVar(player, 'Prog', 7)\n            quest:setVar(player, 'Stage', JstMidnight())\n            player:needToZone(true)\n        end\n    end)\nend)\n"},["modules/era/lua/quests/ahturhgan/navigating_the_unfriendly_seas.lua"]={["Path"]="modules/era/lua/quests/ahturhgan/navigating_the_unfriendly_seas.lua",["SHA256"]="24122860e3fedb08a0edf3e6e6ae09c3f9a2e39637e22f7f637ba437af5c4dd3",["Text"]="-----------------------------------\n-- Navigating the Unfriendly Seas (COR AF2)\n-- Restores the JST midnight wait before the Leypoint finishes with the hydrogauge.\n-- The June 7, 2016 version update shortened the wait to one minute.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/50760-Jun.-7-2016-(JST)-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_navigating_the_unfriendly_seas', xi.pre(xi.expansion.ROV))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/ahtUrhgan/COR_AF2_Navigating_the_Unfriendly_Seas', function(quest)\n        local wajaom    = quest.sections[2][xi.zone.WAJAOM_WOODLANDS]\n        local baseTrade = wajaom['Leypoint'].onTrade\n\n        -- The Leypoint finishes measuring at JST midnight.\n        wajaom['Leypoint'].onTrade = function(player, npc, trade)\n            local action = baseTrade(player, npc, trade)\n            if action then\n                quest:setVar(player, 'Wait', JstMidnight()) -- Module change\n            end\n\n            return action\n        end\n    end)\nend)\n"},["modules/era/lua/quests/ahturhgan/olduum.lua"]={["Path"]="modules/era/lua/quests/ahturhgan/olduum.lua",["SHA256"]="fed33f84303b3610f1f5c5870326c637ac88e31d5d19a1d4ec5ec9ca6db9fb17",["Text"]="-----------------------------------\n-- Olduum\n-- Restores the 24-hour wait for another Olduum Ring.\n-- The June 7, 2016 update reduced this to one minute.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/50760-Jun.-7-2016-(JST)-Version-Update\n-- Source: https://wiki.ffo.jp/html/7472.html\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_olduum', xi.pre(xi.expansion.ROV))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/ahtUrhgan/Olduum', function(quest)\n        local wajaom          = quest.sections[3][xi.zone.WAJAOM_WOODLANDS]\n        local baseEventFinish = wajaom.onEventFinish[2]\n\n        wajaom.onEventFinish[2] = function(player, csid, option, npc)\n            local previousWait = quest:getVar(player, 'Wait')\n            local result       = baseEventFinish(player, csid, option, npc)\n\n            if quest:getVar(player, 'Wait') ~= previousWait then\n                quest:setVar(player, 'Wait', GetSystemTime() + 86400) -- Module change\n            end\n\n            return result\n        end\n    end)\nend)\n"},["modules/era/lua/quests/ahturhgan/omens.lua"]={["Path"]="modules/era/lua/quests/ahturhgan/omens.lua",["SHA256"]="b613ab800dc35d046af8910c61075fd3272819ff22cd849454daa74ca96df317",["Text"]="-----------------------------------\n-- Omens (BLU AF2)\n-- Restores the JST midnight wait before Waoud offers Transformations.\n-- The June 7, 2016 version update shortened the wait to one minute.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/50760-Jun.-7-2016-(JST)-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_omens', xi.pre(xi.expansion.ROV))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/ahtUrhgan/BLU_AF2_Omens', function(quest)\n        local whitegate = quest.sections[2][xi.zone.AHT_URHGAN_WHITEGATE]\n\n        -- Copy of the base handler. Transformations is offered at JST midnight.\n        whitegate.onEventFinish[716] = function(player, csid, option, npc)\n            if quest:complete(player) then\n                player:delKeyItem(xi.keyItem.SEALED_IMMORTAL_ENVELOPE)\n\n                xi.quest.setMustZone(player, xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.TRANSFORMATIONS)\n                xi.quest.setVar(player, xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.TRANSFORMATIONS, 'Timer', JstMidnight()) -- Module change\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/ahturhgan/transformations.lua"]={["Path"]="modules/era/lua/quests/ahturhgan/transformations.lua",["SHA256"]="cc25dd7054a00674370ce29d18f9c154fe6a6dcf6e8f3859cd673fbac26f12a5",["Text"]="-----------------------------------\n-- Transformations (BLU AF3)\n-- Restores the JST midnight wait before Waoud offers The Beast Within.\n-- The June 7, 2016 version update shortened the wait to one minute.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/50760-Jun.-7-2016-(JST)-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_transformations', xi.pre(xi.expansion.ROV))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/ahtUrhgan/BLU_AF3_Transformations', function(quest)\n        local alzadaal = quest.sections[2][xi.zone.ALZADAAL_UNDERSEA_RUINS]\n\n        -- Copy of the base handler. The Beast Within is offered at JST midnight.\n        alzadaal.onEventFinish[5] = function(player, csid, option, npc)\n            if quest:complete(player) then\n                xi.quest.setVar(player, xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.THE_BEAST_WITHIN, 'Timer', JstMidnight()) -- Module change\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/ahturhgan/vanishing_act.lua"]={["Path"]="modules/era/lua/quests/ahturhgan/vanishing_act.lua",["SHA256"]="84323e64a5596a9161f85962a5818cbb0d48c2d285890f62c9f43db67c50156b",["Text"]="-----------------------------------\n-- Vanishing Act\n-- Restores the JST midnight wait before A Taste of Honey opens.\n-- The September 9, 2014 version update shortened the wait to one minute.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/44090-Sep-9-2014-(JST)-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_vanishing_act', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/ahtUrhgan/Vanishing_Act', function(quest)\n        local whitegate = quest.sections[2][xi.zone.AHT_URHGAN_WHITEGATE]\n\n        -- Copy of the base handler. A Taste of Honey opens at JST midnight.\n        whitegate.onEventFinish[45] = function(player, csid, option, npc)\n            if quest:complete(player) then\n                player:needToZone(true)\n                player:delKeyItem(xi.keyItem.RAINBOW_BERRY)\n                xi.quest.setVar(player, xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.A_TASTE_OF_HONEY, 'Stage', JstMidnight()) -- Module change\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/bastok/eco_warrior.lua"]={["Path"]="modules/era/lua/quests/bastok/eco_warrior.lua",["SHA256"]="1b6471bb661e0f3e94ce04af3833d849d2611e523aaa6f1e5874d4afe604eed6",["Text"]="-----------------------------------\n-- Eco-Warrior (Bastok)\n-- Restores the level 20 restriction on the ointment.\n-- The June 25, 2015 version update raised the level cap from 20 to 25.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/47481\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_eco_warrior_bastok', xi.pre(xi.expansion.ROV))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/bastok/Eco_Warrior', function(quest)\n        local gusgenMines = quest.sections[2][xi.zone.GUSGEN_MINES]\n\n        -- Copy of the base handler with the level restriction lowered to 20.\n        gusgenMines.onEventFinish[13] = function(player, csid, option, npc)\n            if option == 1 then\n                player:addStatusEffect(xi.effect.LEVEL_RESTRICTION, {\n                    power    = 20, -- Module change: the level restriction is 20.\n                    subPower = 1,  -- exp uses actual level and not the restricted level.\n                    origin   = player,\n                    flag     = xi.effectFlag.ON_ZONE\n                })\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/bastok/the_gustaberg_tour.lua"]={["Path"]="modules/era/lua/quests/bastok/the_gustaberg_tour.lua",["SHA256"]="cfe65b343f0641a0af0c7d13eb3b4675352054dacfc9ed82571310c45c1f5e0d",["Text"]="-----------------------------------\n-- The Gustaberg Tour\n-- Reverts the completion requirement to six party members of level five or below.\n-- The June 25, 2015 version update reduced it to two members of level fifteen or below.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/47481\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_the_gustaberg_tour', xi.pre(xi.expansion.ROV))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/bastok/The_Gustaberg_Tour', function(quest)\n        local northGustaberg = quest.sections[2][xi.zone.NORTH_GUSTABERG]\n\n        -- Copy of the base handler with the level lowered to 5 and the party size raised to 6.\n        northGustaberg['Hunting_Bear'].onTrigger = function(player, npc)\n            local flag = true\n\n            for _, member in pairs(player:getAlliance()) do\n                if\n                    member:getMainLvl() > 5 or\n                    member:checkDistance(player) > 15\n                then\n                    flag = false\n                end\n            end\n\n            if flag and #player:getParty() == 6 then\n                return quest:progressEvent(22)\n            else\n                return quest:progressEvent(21)\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/hiddenquests/crafted_corsair_artifact.lua"]={["Path"]="modules/era/lua/quests/hiddenquests/crafted_corsair_artifact.lua",["SHA256"]="41afa4747c2f6a4dd0ae266d5b8d2aaaca95e52db4f8eb8dd4e7666c957014cd",["Text"]="-----------------------------------\n-- Crafted Corsair Artifact (COR AF)\n-- Restores the JST midnight wait before a finished piece is handed over.\n-- The June 7, 2016 version update shortened the wait to one Vana'diel day.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/50759\n-- Source: https://forum.square-enix.com/ffxi/threads/50760-Jun.-7-2016-(JST)-Version-Update\n-- Source: https://wiki.ffo.jp/html/5182.html\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_corsair_attire_commission', xi.pre(xi.expansion.ROV))\n\nlocal commissions =\n{\n    -- Corsair's Gants\n    {\n        option   = 1,\n        zoneId   = xi.zone.WINDURST_WATERS,\n        npcName  = 'Door_House',\n        feeCsid  = 946,\n        waitCsid = 945,\n    },\n\n    -- Corsair's Bottes\n    {\n        option   = 2,\n        zoneId   = xi.zone.BASTOK_MINES,\n        npcName  = 'Door_House',\n        feeCsid  = 524,\n        waitCsid = 523,\n    },\n\n    -- Corsair's Frac\n    {\n        option   = 3,\n        zoneId   = xi.zone.PORT_SAN_DORIA,\n        npcName  = 'Raqtibahl',\n        feeCsid  = 760,\n        waitCsid = 757,\n    },\n}\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/hiddenQuests/Crafted_Corsair_Artifact', function(quest)\n        for _, commission in ipairs(commissions) do\n            local zoneSection   = quest.sections[1][commission.zoneId]\n            local baseOnTrigger = zoneSection[commission.npcName].onTrigger\n            local baseHandler   = zoneSection.onEventFinish[commission.feeCsid]\n\n            zoneSection[commission.npcName].onTrigger = function(player, npc)\n                if\n                    quest:getVar(player, 'Prog') == 4 and\n                    quest:getVar(player, 'Option') == commission.option\n                then\n                    if quest:getVar(player, 'Wait') ~= 0 then\n                        -- The base handler checks the craftsman being spoken to.\n                        if baseOnTrigger(player, npc) then\n                            return quest:event(commission.waitCsid)\n                        end\n\n                        return\n                    end\n\n                    -- The base Vana'diel day timer no longer applies.\n                    quest:setVar(player, 'Timer', 0)\n                end\n\n                return baseOnTrigger(player, npc)\n            end\n\n            zoneSection.onEventFinish[commission.feeCsid] = function(player, csid, option, npc)\n                baseHandler(player, csid, option, npc)\n\n                quest:setTimedVar(player, 'Wait', JstMidnight()) -- Module change: Start JST midnight timer\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/hiddenquests/crafted_magus_artifact.lua"]={["Path"]="modules/era/lua/quests/hiddenquests/crafted_magus_artifact.lua",["SHA256"]="bc114089aa6dc6342b0655d44abfb91d61bc4eb737eb3c7169f69578a0a8a66b",["Text"]="-----------------------------------\n-- Crafted Magus Artifact (BLU AF)\n-- Restores the JST midnight wait before another piece can be ordered.\n-- The June 7, 2016 version update shortened the wait to one Vana'diel day.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/50759\n-- Source: https://forum.square-enix.com/ffxi/threads/50760-Jun.-7-2016-(JST)-Version-Update\n-- Source: https://wiki.ffo.jp/html/5181.html\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_magus_attire_commission', xi.pre(xi.expansion.ROV))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/hiddenQuests/Crafted_Magus_Artifact', function(quest)\n        local whitegate     = quest.sections[1][xi.zone.AHT_URHGAN_WHITEGATE]\n        local baseOnTrigger = whitegate['Lathuya'].onTrigger\n\n        whitegate['Lathuya'].onTrigger = function(player, npc)\n            local remainingBLUAF     = player:getCharVar('[BLUAF]Remaining')\n            local totalCraftedPieces = 3 - utils.mask.countBits(remainingBLUAF, 3)\n\n            if\n                player:getCharVar('[BLUAF]Current') == 0 and\n                totalCraftedPieces > 0 and\n                totalCraftedPieces < 3\n            then\n                -- Asleep message, wait until Japanese midnight passes.\n                if player:getCharVar('[BLUAF]RestingTimer') ~= 0 then\n                    return quest:event(737 + (8 * totalCraftedPieces - 8))\n                end\n\n                -- The base Vana'diel day timer no longer applies.\n                player:setCharVar('[BLUAF]RestingDay', 0)\n            end\n\n            return baseOnTrigger(player, npc)\n        end\n\n        -- Each piece is handed over by its own event.\n        for _, eventId in ipairs({ 736, 744, 752 }) do\n            local baseHandler = whitegate.onEventFinish[eventId]\n\n            whitegate.onEventFinish[eventId] = function(player, csid, option, npc)\n                -- The base handler clears the bit for the piece handed over.\n                local remainingBLUAF = player:getCharVar('[BLUAF]Remaining')\n\n                baseHandler(player, csid, option, npc)\n\n                -- A piece was handed over and another remains.\n                if\n                    player:getCharVar('[BLUAF]Remaining') ~= 0 and\n                    player:getCharVar('[BLUAF]Remaining') ~= remainingBLUAF\n                then\n                    player:setCharVar('[BLUAF]RestingTimer', 1, JstMidnight()) -- Module change: Start JST midnight timer\n                end\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/hiddenquests/crafted_puppetry_artifact.lua"]={["Path"]="modules/era/lua/quests/hiddenquests/crafted_puppetry_artifact.lua",["SHA256"]="70f6d952dc9fd6b21c085f281a726903dff7d26026252086d041906f1ee0c0a0",["Text"]="-----------------------------------\n-- Crafted Puppetry Artifact (PUP AF)\n-- Restores the JST midnight wait before a finished piece is handed over.\n-- The June 7, 2016 version update shortened the wait to one Vana'diel day.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/50759\n-- Source: https://forum.square-enix.com/ffxi/threads/50760-Jun.-7-2016-(JST)-Version-Update\n-- Source: https://wiki.ffo.jp/html/5183.html\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_puppetry_attire_commission', xi.pre(xi.expansion.ROV))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/hiddenQuests/Crafted_Puppetry_Artifact', function(quest)\n        local whitegate     = quest.sections[1][xi.zone.AHT_URHGAN_WHITEGATE]\n        local baseOnTrigger = whitegate['Dhima_Polevhia'].onTrigger\n        local baseHandler   = whitegate.onEventFinish[795]\n\n        whitegate['Dhima_Polevhia'].onTrigger = function(player, npc)\n            if player:getCharVar('[PUP]orderStage') == 2 then\n                if player:getCharVar('[PUP]orderWait') ~= 0 then\n                    return quest:event(796) -- Order is not ready.\n                end\n\n                -- The base Vana'diel day timer no longer applies.\n                player:setCharVar('[PUP]orderTime', 0)\n            end\n\n            return baseOnTrigger(player, npc)\n        end\n\n        whitegate.onEventFinish[795] = function(player, csid, option, npc)\n            baseHandler(player, csid, option, npc)\n\n            -- Work starts when the materials are traded.\n            player:setCharVar('[PUP]orderWait', 1, JstMidnight()) -- Module change: Start JST midnight timer\n        end\n    end)\nend)\n"},["modules/era/lua/quests/jeuno/all_in_the_cards.lua"]={["Path"]="modules/era/lua/quests/jeuno/all_in_the_cards.lua",["SHA256"]="5bfe6cea9eed9f39f796d7afd0d87e2946f976e63004392927b4685658f1ba73",["Text"]="-----------------------------------\n-- All in the Cards\n-- Removes the quest. Chululu did not offer it before the July 12, 2011 version update.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/11231-July-12-2011-(JST)-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_all_in_the_cards', xi.pre(xi.expansion.ABYSSEA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/jeuno/All_in_the_Cards', function(quest)\n        -- The first offer and the repeat offer. A player already holding the quest can still turn it in.\n        quest.sections[1].check = function(player, status, vars)\n            return false\n        end\n\n        quest.sections[2].check = function(player, status, vars)\n            return false\n        end\n    end)\nend)\n"},["modules/era/lua/quests/jeuno/apocalypse_nigh.lua"]={["Path"]="modules/era/lua/quests/jeuno/apocalypse_nigh.lua",["SHA256"]="ff286780f96ba6866d99abb1de405f5734d0ec118f5d9d687740b01295b5a312",["Text"]="-----------------------------------\n-- Apocalypse Nigh\n-- Restores the JST midnight waits before this quest can be started and after the Empyreal Paradox battlefield is cleared.\n-- The wait for Gilgamesh's reward cutscene in Norg is not tied to Aldo's cutscene.\n-- The wait after the battlefield was left alone until the November 10, 2021 version update shortened it to one Vana'diel day.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/58770\n-- Source: https://wiki.ffo.jp/html/7291.html\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_apocalypse_nigh', xi.pre(xi.expansion.TVR))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/jeuno/Apocalypse_Nigh', function(quest)\n        local empyrealParadox = quest.sections[2][xi.zone.EMPYREAL_PARADOX]\n        local norg            = quest.sections[2][xi.zone.NORG]\n\n        -- Copy of the base check with the timer compared as a timestamp.\n        quest.sections[1].check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.SHADOWS_OF_THE_DEPARTED) and\n                GetSystemTime() >= vars.Timer and -- Module change: this quest opens at JST midnight.\n                not quest:getMustZone(player)\n        end\n\n        -- Copy of the base handler with the one Vana'diel day wait extended to JST midnight.\n        empyrealParadox.onEventFinish[32001] = function(player, csid, option, npc)\n            if\n                player:getLocalVar('battlefieldWin') == xi.battlefield.id.APOCALYPSE_NIGH and\n                quest:getVar(player, 'Prog') == 3\n            then\n                quest:setVar(player, 'Prog', 4)\n                quest:setVar(player, 'Timer', JstMidnight()) -- Module change: the wait runs to JST midnight.\n            end\n        end\n\n        -- Copy of the base handler with the timer compared as a timestamp.\n        norg['_700'].onTrigger = function(player, npc)\n            if\n                quest:getVar(player, 'Prog') == 5 and\n                GetSystemTime() < quest:getVar(player, 'Timer') -- Module change: Gilgamesh is unavailable until JST midnight.\n            then\n                return quest:progressEvent(235)\n            end\n        end\n\n        -- Copy of the base handler with the timer compared as a timestamp.\n        norg['Gilgamesh'].onTrigger = function(player, npc)\n            if\n                GetSystemTime() >= quest:getVar(player, 'Timer') and -- Module change: Gilgamesh waits until JST midnight.\n                not quest:getMustZone(player)\n            then\n                local questProgress = quest:getVar(player, 'Prog')\n\n                if questProgress == 5 then\n                    return quest:progressEvent(232, 252, 6)\n                elseif questProgress == 6 then\n                    return quest:progressEvent(234, 252)\n                end\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/jeuno/chocobos_wounds.lua"]={["Path"]="modules/era/lua/quests/jeuno/chocobos_wounds.lua",["SHA256"]="775217f5fda57c88fcecb9c42941e1d180c6137014108e64a04aadd5a403b01d",["Text"]="-----------------------------------\n-- Chocobo's Wounds\n-- Reverts feeding timers to one Vana'diel day.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/46068-Feb-19-2015-%28JST%29-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_chocobos_wounds', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/jeuno/Chocobos_Wounds', function(quest)\n        -- Override trade function timer with VanadielUniqueDay instead of GetSystemTime +45\n        quest.sections[2][xi.zone.UPPER_JEUNO]['Chocobo'].onTrade = function(player, npc, trade)\n            if trade:getItemQty(xi.item.BUNCH_OF_GYSAHL_GREENS) > 0 then\n                return quest:event(76)\n            end\n\n            if trade:getItemQty(xi.item.CLUMP_OF_GAUSEBIT_WILDGRASS) == 0 then\n                return quest:noAction()\n            end\n\n            if quest:getVar(player, 'Timer') >= VanadielUniqueDay() then\n                return quest:event(73)\n            end\n\n            local eventTable =\n            {\n                [1] = 57,\n                [2] = 58,\n                [3] = 99,\n                [4] = 59,\n                [5] = 60,\n                [6] = 64,\n            }\n\n            local questProgress = quest:getVar(player, 'Prog')\n            if questProgress <= 2 then\n                return quest:progressEvent(eventTable[questProgress])\n            end\n\n            if npcUtil.tradeHasExactly(trade, xi.item.CLUMP_OF_GAUSEBIT_WILDGRASS) then\n                return quest:progressEvent(eventTable[questProgress])\n            end\n        end\n\n        quest.sections[2][xi.zone.UPPER_JEUNO].onEventFinish[57] = function(player, csid, option, npc)\n            quest:setVar(player, 'Timer', VanadielUniqueDay())\n            quest:setVar(player, 'Prog', 2)\n        end\n\n        quest.sections[2][xi.zone.UPPER_JEUNO].onEventFinish[58] = function(player, csid, option, npc)\n            quest:setVar(player, 'Timer', VanadielUniqueDay())\n            quest:setVar(player, 'Prog', 3)\n        end\n\n        quest.sections[2][xi.zone.UPPER_JEUNO].onEventFinish[59] = function(player, csid, option, npc)\n            quest:setVar(player, 'Timer', VanadielUniqueDay())\n            quest:setVar(player, 'Prog', 5)\n            player:confirmTrade()\n        end\n\n        quest.sections[2][xi.zone.UPPER_JEUNO].onEventFinish[60] = function(player, csid, option, npc)\n            quest:setVar(player, 'Timer', VanadielUniqueDay())\n            quest:setVar(player, 'Prog', 6)\n            player:confirmTrade()\n        end\n\n        quest.sections[2][xi.zone.UPPER_JEUNO].onEventFinish[99] = function(player, csid, option, npc)\n            quest:setVar(player, 'Timer', VanadielUniqueDay())\n            quest:setVar(player, 'Prog', 4)\n            player:confirmTrade()\n        end\n    end)\nend)\n"},["modules/era/lua/quests/jeuno/collect_tarut_cards.lua"]={["Path"]="modules/era/lua/quests/jeuno/collect_tarut_cards.lua",["SHA256"]="aa5ab2357614ace7b037ce789728a20dabd5f67cd2b49a34fc78053147456965",["Text"]="-----------------------------------\n-- Collect Tarut Cards\n-- Removes the extra batch of cards. Chululu gives five cards once, when the quest is accepted.\n-- The July 12, 2011 version update let her hand out a new batch after each conquest tally.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/11231-July-12-2011-(JST)-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_collect_tarut_cards', xi.pre(xi.expansion.ABYSSEA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/jeuno/Collect_Tarut_Cards', function(quest)\n        quest.sections[2][xi.zone.LOWER_JEUNO]['Chululu'].onTrigger = function(player, npc)\n            return quest:event(27) -- Reminder\n        end\n    end)\nend)\n"},["modules/era/lua/quests/jeuno/northward.lua"]={["Path"]="modules/era/lua/quests/jeuno/northward.lua",["SHA256"]="f86dda2b6b97ce4cd8c72fd4f2c90c570f34f4473d2bb87b971e86dd9eea83fd",["Text"]="-----------------------------------\n-- Module to remove exp and gil from 'Northward' quest reward.\n-- Gil and exp were added to the quest reward in 2013 so they are removed here.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/38100\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_northward', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/jeuno/Northward', function(quest)\n        quest.reward = {\n            keyItem  = xi.keyItem.MAP_OF_CASTLE_ZVAHL,\n            title    = xi.title.ENVOY_TO_THE_NORTH,\n        }\n    end)\nend)\n"},["modules/era/lua/quests/jeuno/shadows_of_the_departed.lua"]={["Path"]="modules/era/lua/quests/jeuno/shadows_of_the_departed.lua",["SHA256"]="26e1040f8b78da0944530c4b2a5e6ef7e8469d62d751e5d9317e11d4f6fa55ca",["Text"]="-----------------------------------\n-- Shadows of the Departed\n-- Restores the JST midnight waits before this quest can be started and before Apocalypse Nigh can be started.\n-- Prishe's trust was added on February 18, 2014, and the follow-up patch on February 20 changed both waits to a Vana'diel date change.\n-- That patch was never documented; the date comes from the JP quest wiki.\n-----------------------------------\n-- Source: https://wiki.ffo.jp/html/5557.html\n-- Source: https://wiki.ffo.jp/html/7291.html\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_shadows_of_the_departed', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/jeuno/Shadows_of_the_Departed', function(quest)\n        local ruludeGardens = quest.sections[2][xi.zone.RULUDE_GARDENS]\n\n        -- Copy of the base check with the timer compared as a timestamp.\n        quest.sections[1].check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.STORMS_OF_FATE) and\n                player:getCurrentMission(xi.mission.log_id.ZILART) == xi.mission.id.zilart.AWAKENING and\n                player:getMissionStatus(xi.mission.log_id.ZILART) == 3 and\n                GetSystemTime() >= vars.Timer -- Module change: this quest opens at JST midnight.\n        end\n\n        -- Copy of the base handler with the one Vana'diel day wait extended to JST midnight.\n        ruludeGardens.onEventFinish[162] = function(player, csid, option, npc)\n            if quest:complete(player) then\n                for keyItemId = xi.keyItem.PROMYVION_HOLLA_SLIVER, xi.keyItem.PROMYVION_HOLLA_SLIVER + 2 do\n                    player:delKeyItem(keyItemId)\n                end\n\n                player:messageSpecial(zones[xi.zone.RULUDE_GARDENS].text.YOU_HAND_THE_THREE_SLIVERS)\n\n                xi.quest.setVar(player, xi.questLog.JEUNO, xi.quest.id.jeuno.APOCALYPSE_NIGH, 'Timer', JstMidnight()) -- Module change: Apocalypse Nigh opens at JST midnight.\n                xi.quest.setMustZone(player, xi.questLog.JEUNO, xi.quest.id.jeuno.APOCALYPSE_NIGH)\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/jeuno/storms_of_fate.lua"]={["Path"]="modules/era/lua/quests/jeuno/storms_of_fate.lua",["SHA256"]="375ccd826fd6b557805bae4a930849649e72e6cfa0a5c7e77bb826f05e25e024",["Text"]="-----------------------------------\n-- Storms of Fate\n-- Restores the JST midnight wait before Shadows of the Departed can be started.\n-- Prishe's trust was added on February 18, 2014, and the follow-up patch on February 20 changed the wait to a Vana'diel date change.\n-- That patch was never documented; the date comes from the JP quest wiki.\n-----------------------------------\n-- Source: https://wiki.ffo.jp/html/5557.html\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_storms_of_fate', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/jeuno/Storms_of_Fate', function(quest)\n        local ruludeGardens = quest.sections[2][xi.zone.RULUDE_GARDENS]\n\n        -- Copy of the base handler with the one Vana'diel day wait extended to JST midnight.\n        ruludeGardens.onEventFinish[143] = function(player, csid, option, npc)\n            if quest:complete(player) then\n                xi.quest.setVar(player, xi.questLog.JEUNO, xi.quest.id.jeuno.SHADOWS_OF_THE_DEPARTED, 'Timer', JstMidnight()) -- Module change: Shadows of the Departed opens at JST midnight.\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/jeuno/the_circle_of_time.lua"]={["Path"]="modules/era/lua/quests/jeuno/the_circle_of_time.lua",["SHA256"]="29d3360c272fd494df4747c56049ce522e22ba0f3934f4f28b7950809fe2272b",["Text"]="-----------------------------------\n-- The Circle of Time (BRD AF3)\n-- Restores the JST midnight wait for the star ring buried in the perennial snow.\n-- The June 17, 2014 version update shortened the wait to about one minute.\n-- The quest appears in the Japanese notes only; the English notes omit it from the list.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/42611\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_the_circle_of_time', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/jeuno/The_Circle_of_Time', function(quest)\n        local xarcabard = quest.sections[2][xi.zone.XARCABARD]\n\n        -- Copy of the base handler with the 30 second wait extended to JST midnight.\n        xarcabard.onEventFinish[3] = function(player, csid, option, npc)\n            if option == 0 then\n                quest:setVar(player, 'Buried', JstMidnight()) -- Module change: the ring is purified at JST midnight.\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/jeuno/the_gobbiebag_part_1_to_10.lua"]={["Path"]="modules/era/lua/quests/jeuno/the_gobbiebag_part_1_to_10.lua",["SHA256"]="28923ce6c1a95954d4d8821b398145ea38714ece1d075d56492ee5834a68b815",["Text"]="-----------------------------------\n-- Increases the fame requirements for the Gobbiebag quests in Jeuno back to 75 era.\n-- Requirements were lowered on Feb. 18th, 2014 : https://wiki.ffo.jp/html/30645.html\n-----------------------------------\nrequire('modules/module_utils')\nrequire('scripts/quests/jeuno/helpers')\n-----------------------------------\nlocal m = Module:new('era_gobbiebag_fame_requirements', xi.pre(xi.expansion.SOA))\n\nlocal eraFameRequirements =\n{\n    [xi.quest.id.jeuno.THE_GOBBIEBAG_PART_I   ] = 3,\n    [xi.quest.id.jeuno.THE_GOBBIEBAG_PART_II  ] = 4,\n    [xi.quest.id.jeuno.THE_GOBBIEBAG_PART_III ] = 5,\n    [xi.quest.id.jeuno.THE_GOBBIEBAG_PART_IV  ] = 5,\n    [xi.quest.id.jeuno.THE_GOBBIEBAG_PART_V   ] = 6,\n    [xi.quest.id.jeuno.THE_GOBBIEBAG_PART_VI  ] = 6,\n    [xi.quest.id.jeuno.THE_GOBBIEBAG_PART_VII ] = 7,\n    [xi.quest.id.jeuno.THE_GOBBIEBAG_PART_VIII] = 7,\n    [xi.quest.id.jeuno.THE_GOBBIEBAG_PART_IX  ] = 8,\n    [xi.quest.id.jeuno.THE_GOBBIEBAG_PART_X   ] = 9,\n}\n\nm:addOverride('xi.jeuno.helpers.GobbiebagQuest.new', function(self, params)\n    params.fame = eraFameRequirements[params.questId] or params.fame\n\n    local quest = super(self, params)\n\n    table.insert(quest.sections,\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getContainerSize(xi.inv.INVENTORY) == params.startInventorySize and\n                player:getFameLevel(xi.fameArea.JEUNO) < params.fame and\n                (params.prerequisite == nil or player:hasCompletedQuest(xi.questLog.JEUNO, params.prerequisite))\n        end,\n\n        -- Restores the original lines for the quest before fame requirements were abolished.\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Bluffnix'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(42, player:getContainerSize(xi.inv.INVENTORY) + 1)\n                end,\n            },\n        },\n    })\n\n    return quest\nend)\n"}};
